  "You can read and send messages here as the spare account. Every message is one you type and send yourself. Discord may flag automated or self-bot use, so keep it to a spare account.": "Aquí puedes leer y enviar mensajes como la cuenta de reserva. Cada mensaje lo escribes y envías tú. Discord puede marcar el uso automatizado o de self-bot, así que úsalo solo con una cuenta de reserva.",
  "Paste keys from your own accounts. They stay encrypted, and the saved value is never shown again.": "Pega las claves de tus propias cuentas. Se guardan cifradas y el valor guardado no se vuelve a mostrar.",
