  "This permanently deletes this account. Your profile, photos, sessions, follows, followers, friends, notification tabs, feed settings, groups, drafts, likes, bookmarks, watch history, community posts, vault, drive files, linked accounts, and uploads are removed. The handle can stay reserved so nobody else can take it. This cannot be undone.": "Esto elimina la cuenta de forma permanente. Se borran el perfil, las fotos, las sesiones, los seguidos, los seguidores, los amigos, las pestañas de notificaciones, los ajustes del feed, los grupos, los borradores, los me gusta, los guardados, el historial, las publicaciones de comunidades, la caja fuerte, los archivos, las cuentas vinculadas y las subidas. El nombre puede quedar reservado para que nadie más lo use. Esto no se puede deshacer.",
