  "Max": "Máximo",
  "Light does less and leaves feeds, search, and translation on the server.": "Ligero hace menos y deja las fuentes, la búsqueda y la traducción en el servidor.",
  "Balanced is the default. This device does the work it can, and the server covers the rest.": "Equilibrado es el valor predeterminado. Este dispositivo hace lo que puede y el servidor cubre el resto.",
  "Max does as much as it can. A large on-device model stays off until you turn it on.": "Máximo hace todo lo que puede. Un modelo grande en el dispositivo sigue apagado hasta que lo actives.",
