  "Search on this device": "Buscar en este dispositivo",
  "Search uses posts already on this device. The server is used only for the rest.": "La búsqueda usa publicaciones que ya están en este dispositivo. El servidor se usa solo para el resto.",
  "Translate on this device": "Traducir en este dispositivo",
  "Use the browser translator when it is available. The current translation path is the backup.": "Usa el traductor del navegador cuando esté disponible. La ruta de traducción actual es el respaldo.",
  "On-device assistant": "Asistente en el dispositivo",
  "The browser model goes first. A cloud provider runs only when you add one. No paid API is built in.": "El modelo del navegador va primero. Un proveedor en la nube solo funciona si lo añades. No hay una API de pago integrada.",
