  "Passkeys, app lock, and the privacy screen.": "Llaves de acceso, bloqueo de la app y la pantalla de privacidad.",
  "Passkeys": "Llaves de acceso",
  "Sign in to add a passkey to this account.": "Entra para añadir una llave de acceso a esta cuenta.",
  "Passkeys are not available in this browser.": "Las llaves de acceso no están disponibles en este navegador.",
