  "Last used {date}": "Último uso {date}",
  "Remove this passkey?": "¿Quitar esta llave de acceso?",
  "A passkey uses this device's fingerprint, face, or screen lock. No password is required. The account number still works as an optional backup.": "Una llave de acceso usa la huella, la cara o el bloqueo de pantalla de este dispositivo. No hace falta contraseña. El número de cuenta sigue como respaldo opcional.",
  "Passkeys stay on the site where you created them. A passkey made on one site does not sign in on the other.": "Las llaves de acceso se quedan en el sitio donde las creaste. Una llave de un sitio no entra en el otro.",
  "Choose a phone or tablet when you want a QR code for cross-device sign-in.": "Elige un teléfono o una tableta cuando quieras un código QR para entrar desde otro dispositivo.",
  "No passkeys on this site yet.": "Todavía no hay llaves de acceso en este sitio.",
  "Add a passkey": "Añadir una llave de acceso",
  "Covered": "Oculto",
  "Privacy screen": "Pantalla de privacidad",
  "Cover the app when this window is hidden, in the background, or locked.": "Cubre la app cuando esta ventana está oculta, en segundo plano o bloqueada.",
  "Messages only": "Solo mensajes",
  "Whole app": "Toda la app",
  "The cover is one layer. It does not blur, hide, or restyle the page, and it goes away when this window is in front.": "Es una sola capa. No desenfoca, no oculta ni cambia la página, y desaparece cuando esta ventana vuelve al frente.",
  "Android can block screenshots only in a wrapper that sets FLAG_SECURE. This site does not include that wrapper.": "Android solo puede bloquear capturas en un contenedor que active FLAG_SECURE. Este sitio no incluye ese contenedor.",
  "Stop text selection in messages": "Impedir seleccionar texto en los mensajes",
  "Unlock to open the app": "Desbloquea para abrir la app",
  "The sensor encrypts drafts, messages, and the on-device copy. Unlock works with no internet.": "El sensor cifra los borradores, los mensajes y la copia de este dispositivo. El desbloqueo funciona sin internet.",
  "This browser cannot tie encryption to the sensor. The sensor approves unlock, and the PIN encrypts data on this device. A person with the PIN and a copy of this storage can decrypt it without the sensor.": "Este navegador no puede atar el cifrado al sensor. El sensor aprueba el desbloqueo y el PIN cifra los datos en este dispositivo. Quien tenga el PIN y una copia de este almacenamiento puede descifrarlo sin el sensor.",
  "Device PIN": "PIN del dispositivo",
  "Unlock": "Desbloquear",
  "Forgot": "Olvidé",
  "This signs you out and erases drafts, messages, and other data saved on this device.": "Esto cierra la sesión y borra borradores, mensajes y otros datos guardados en este dispositivo.",
  "Erase and sign out": "Borrar y cerrar sesión",
  "App lock": "Bloqueo de la app",
