  "Too many attempts. Wait and try again.": "Demasiados intentos. Espera y vuelve a probar.",
  "Wrong PIN or the sensor was not recognized.": "PIN incorrecto o el sensor no se reconoció.",
  "Save this account number. You can sign in with a passkey later. The number is an optional backup.": "Guarda este número de cuenta. Luego puedes entrar con una llave de acceso. El número es un respaldo opcional.",
  "Create a passkey": "Crear una llave de acceso",
  "Continue without a passkey": "Continuar sin llave de acceso",
  "Sign in with a passkey": "Entrar con una llave de acceso",
  "Could not verify that passkey.": "No se pudo comprobar esa llave de acceso.",
  "There is no password to reset. A passkey can sign in, and the account number from sign-up still works.": "No hay contraseña que restablecer. Una llave de acceso puede entrar, y el número de cuenta del registro sigue sirviendo.",
  "On-device AI": "IA en el dispositivo",
  "Language detection and the spam filter are included. Larger downloads stay off until you turn them on. They wait for Wi-Fi, a battery that is not low, and data saver to be off.": "La detección de idioma y el filtro de spam vienen incluidos. Las descargas grandes siguen apagadas hasta que las actives. Esperan a Wi-Fi, a una batería que no esté baja y a que el ahorro de datos esté apagado.",
  "Detect language on this device": "Detectar el idioma en este dispositivo",
  "Included. No download. The browser detector is used when it exists.": "Incluido. Sin descarga. Se usa el detector del navegador cuando existe.",
  "Hide likely spam": "Ocultar el spam probable",
  "Included. No download. Replies, messages, and notifications stay hidden behind Show.": "Incluido. Sin descarga. Respuestas, mensajes y notificaciones quedan ocultos detrás de Mostrar.",
  "Summaries on this device": "Resúmenes en este dispositivo",
  "Included. No download. Long posts, threads, unread messages, and Catch me up use this device first.": "Incluido. Sin descarga. Las publicaciones largas, los hilos, los mensajes no leídos y Ponte al día usan primero este dispositivo.",
  "Compose help on this device": "Ayuda al escribir en este dispositivo",
  "Included. No download. Suggestions, grammar, and tone stay here unless you allow a server.": "Incluido. Sin descarga. Las sugerencias, la gramática y el tono se quedan aquí, salvo que permitas un servidor.",
  "Search saved posts by meaning": "Buscar publicaciones guardadas por significado",
  "Off until you turn it on. The included ranker needs no download.": "Apagado hasta que lo actives. El orden incluido no necesita descarga.",
  "Download a search model": "Descargar un modelo de búsqueda",
  "About {size}. Apache-2.0. Off until you turn it on.": "Unos {size}. Apache-2.0. Apagado hasta que lo actives.",
  "About {size}, plus a small runtime that is cached after the first download. Apache-2.0. Off until you turn it on.": "Unos {size}, más un runtime pequeño que queda en caché tras la primera descarga. Apache-2.0. Apagado hasta que lo actives.",
  "Download a translation model": "Descargar un modelo de traducción",
  "About {size} for a language pair. Off until you turn it on. OPUS-MT is CC-BY-4.0.": "Unos {size} por par de idiomas. Apagado hasta que lo actives. OPUS-MT es CC-BY-4.0.",
  "Auto-translate direct messages": "Traducir automáticamente los mensajes directos",
  "Off until you turn it on. Direct messages are translated on this device only.": "Apagado hasta que lo actives. Los mensajes directos se traducen solo en este dispositivo.",
  "Allow server fallback for direct messages": "Permitir el servidor de reserva para mensajes directos",
  "Off. Message text stays on this device unless you turn this on.": "Apagado. El texto de los mensajes se queda en este dispositivo salvo que actives esto.",
  "Available on Max. About {size}. It stays off until you accept the download. Built with Llama.": "Disponible en Máximo. Unos {size}. Sigue apagado hasta que aceptes la descarga. Built with Llama.",
  "Built with Llama. Llama 3.2 is licensed under the Llama 3.2 Community License, Copyright © Meta Platforms, Inc. All Rights Reserved.": "Built with Llama. Llama 3.2 is licensed under the Llama 3.2 Community License, Copyright © Meta Platforms, Inc. All Rights Reserved.",
