  "{n} reactions": "{n} reacciones",
  "Smart Auto: media from sites that are blocked in your country, or that failed to load on this device, comes through our servers. Photos and videos keep their original quality.": "Auto inteligente: las fotos y videos de sitios bloqueados en tu país, o que no cargaron en este dispositivo, pasan por nuestros servidores. Mantienen su calidad original.",
  "{ms} ms": "{ms} ms",
  "not reachable": "sin conexión",
  "If the app is slow or won't load": "Si la app va lenta o no carga",
  "The app keeps your feed on this device, so saved posts open even with a bad connection. When our main server stalls, it switches to the backup server by itself.": "La app guarda tu feed en este dispositivo, así que los posts guardados se abren incluso con mala conexión. Si nuestro servidor principal se atasca, pasa solo al servidor de respaldo.",
  "Checking…": "Comprobando…",
  "Check connection": "Comprobar conexión",
  "In India": "En India",
  "Some internet providers block sites through DNS. Turning on secure DNS usually fixes it:": "Algunos proveedores de internet bloquean sitios mediante DNS. Activar el DNS seguro suele solucionarlo:",
  "Android: Settings > Network & internet > Private DNS > enter dns.google or one.one.one.one": "Android: Ajustes > Redes e internet > DNS privado > escribe dns.google o one.one.one.one",
  "Chrome or Edge: Settings > Privacy and security > Use secure DNS": "Chrome o Edge: Configuración > Privacidad y seguridad > Usar DNS seguro",
  "Firefox: Settings > Privacy & Security > DNS over HTTPS > Increased protection": "Firefox: Ajustes > Privacidad y seguridad > DNS sobre HTTPS > Protección aumentada",
  "iPhone: install a secure DNS app such as Cloudflare 1.1.1.1": "iPhone: instala una app de DNS seguro, como Cloudflare 1.1.1.1",
  "In Russia": "En Rusia",
  "Smart Auto sends blocked photos and videos through our own servers, and friends who already have a post can pass it to you directly (peer sharing). This helps, but some blocks can't be avoided without a VPN, so we can't promise everything will load.": "Auto inteligente envía las fotos y videos bloqueados por nuestros propios servidores, y los amigos que ya tienen un post pueden pasártelo directamente (compartir entre pares). Ayuda, pero algunos bloqueos no se pueden evitar sin una VPN, así que no podemos prometer que todo cargue.",
