  "Sticker packs and items you buy for yourself are delivered right away. By asking for that, you agree that the {n}-day right to cancel ends at delivery.": "Los paquetes de stickers y los artículos que compras para ti se entregan de inmediato. Al pedirlo, aceptas que el derecho de desistimiento de {n} días termina con la entrega.",
