  "Viktorychs are earned by real effort and are never sold. They have no cash value and can only be spent on gifts and stickers.": "Los Viktorychs se ganan con esfuerzo real y nunca se venden. No tienen valor en efectivo y solo se pueden gastar en regalos y stickers.",
  "Viktorychs earned through abuse, such as fake accounts or self-engagement, can be removed.": "Los Viktorychs ganados con abusos, como cuentas falsas o interacciones contigo mismo, pueden retirarse.",
  "Viktorychs have no cash value and can’t be refunded once spent.": "Los Viktorychs no tienen valor en efectivo y no se reembolsan una vez gastados.",
  "Viktorychs have no cash value. They can’t be bought, cashed out or transferred for money, and they can’t be refunded once spent.": "Los Viktorychs no tienen valor en efectivo. No se pueden comprar, cobrar ni transferir por dinero, y no se reembolsan una vez gastados.",
