  "You can pay for an item with money, through our payment provider, or with Viktorychs. Viktorychs are earned by taking part and are never sold.": "Puedes pagar un artículo con dinero, a través de nuestro proveedor de pagos, o con Viktorychs. Los Viktorychs se ganan participando y nunca se venden.",
  "You can’t send gifts to someone who blocked you or who doesn’t accept gifts from you. Gifting is rate-limited to stop spam.": "No puedes enviar regalos a alguien que te bloqueó o que no acepta regalos tuyos. Los regalos tienen un límite para evitar el spam.",
