  "Reduce motion is on, so achievements fade in quietly without sound or rumble.": "La reducción de movimiento está activada: los logros aparecen sin sonido ni vibración.",
  "Gentle": "Suave",
  "Add this page to your TV browser's bookmarks, or its home screen if it offers that.": "Añade esta página a los marcadores del navegador de la TV, o a su pantalla de inicio si lo permite.",
  "Code": "Código",
  "Code on the TV": "Código de la TV",
  "Codes are 6 letters and numbers.": "Los códigos tienen 6 letras y números.",
  "Could not reach the server. Check the TV's internet connection.": "No se pudo conectar con el servidor. Revisa la conexión a internet de la TV.",
  "Could not reach the server. Try again.": "No se pudo conectar con el servidor. Inténtalo de nuevo.",
  "Done. The TV signs in within a few seconds.": "Listo. La TV iniciará sesión en unos segundos.",
  "Fire TV: in Silk, open the menu and add a bookmark.": "Fire TV: en Silk, abre el menú y añade un marcador.",
  "Get a new code": "Obtener un código nuevo",
  "Keep it one button away": "Tenlo a un botón",
  "LG: in Web Browser, open the menu and add a bookmark. Some models can also pin it to Home.": "LG: en el navegador web, abre el menú y añade un marcador. Algunos modelos también permiten fijarla en Inicio.",
  "Link a TV": "Vincular una TV",
  "On the TV, open {app} and choose Sign in with your phone. Then enter the code from the TV screen, or scan its QR code with this phone's camera.": "En la TV, abre {app} y elige Iniciar sesión con tu teléfono. Luego escribe el código de la pantalla de la TV o escanea su código QR con la cámara de este teléfono.",
  "On your phone, scan the QR code with the camera.": "En tu teléfono, escanea el código QR con la cámara.",
  "Only link a TV you can see in front of you. Anyone using that TV can use your account until you remove it in My devices.": "Vincula solo una TV que tengas delante. Quien use esa TV podrá usar tu cuenta hasta que la quites en Mis dispositivos.",
  "Or open {app} on your phone, go to Settings, then Link a TV, and enter this code:": "O abre {app} en tu teléfono, ve a Configuración, luego Vincular una TV, y escribe este código:",
  "QR code to sign in this TV": "Código QR para iniciar sesión en esta TV",
  "Samsung: in Internet, open the menu and add a bookmark. Some models can also add it to the Home screen.": "Samsung: en Internet, abre el menú y añade un marcador. Algunos modelos también permiten añadirla a la pantalla de inicio.",
  "Sign a TV in with the code it shows. Nothing to type on the TV.": "Inicia sesión en una TV con el código que muestra. No hay que escribir nada en la TV.",
  "Sign in on this phone first, then open this page again to link the TV.": "Primero inicia sesión en este teléfono y luego vuelve a abrir esta página para vincular la TV.",
  "Sign in the TV": "Iniciar sesión en la TV",
  "Sign in with your phone": "Iniciar sesión con tu teléfono",
  "Signed in. Opening your timeline…": "Sesión iniciada. Abriendo tu cronología…",
  "That code didn't work. Check the TV, or get a new code there.": "Ese código no funcionó. Revisa la TV o pide allí un código nuevo.",
  "The TV shows up in My devices, where you can remove it at any time.": "La TV aparece en Mis dispositivos, donde puedes quitarla cuando quieras.",
  "The code works once and expires in 5 minutes.": "El código sirve una vez y caduca en 5 minutos.",
  "This code expired.": "Este código caducó.",
  "Use a phone that is already signed in. Nothing to type on the TV.": "Usa un teléfono que ya tenga la sesión iniciada. No hay que escribir nada en la TV.",
  "Use the arrows on your remote, then press OK.": "Usa las flechas del control remoto y luego pulsa OK.",
  "Waiting for your phone…": "Esperando tu teléfono…",
  "Tap Copy TV link above.": "Toca Copiar enlace para la TV arriba.",
  "Open {app} on your phone and pick your TV. The phone and the TV need the same Wi-Fi.": "Abre {app} en el teléfono y elige tu TV. El teléfono y la TV deben estar en la misma Wi-Fi.",
  "Open the TV remote in {app}.": "Abre el control remoto de la TV en {app}.",
  "On the TV, open the Internet app and select the address bar so the TV keyboard opens.": "En la TV, abre la app Internet y selecciona la barra de direcciones para que se abra el teclado de la TV.",
  "Your phone now shows a keyboard. Touch and hold, tap Paste, then Done.": "El teléfono muestra un teclado. Mantén pulsado, toca Pegar y luego Listo.",
  "This works in Samsung's own Internet browser, because it uses the TV keyboard. Other TV apps may ignore the phone keyboard.": "Funciona en el navegador Internet de Samsung, porque usa el teclado de la TV. Otras apps de la TV pueden ignorar el teclado del teléfono.",
  "Paste the link into the search bar at the top of the TV screen in {app} and search.": "Pega el enlace en la barra de búsqueda de la parte superior de la pantalla de la TV en {app} y busca.",
  "On the TV, choose Web. The link opens in the TV's Web Browser.": "En la TV, elige Web. El enlace se abre en el navegador web de la TV.",
  "The menus differ a little between webOS versions. If you only see the remote, open the Web Browser on the TV, select the address bar and paste with the keyboard button in {app}.": "Los menús cambian un poco según la versión de webOS. Si solo ves el control remoto, abre el navegador web en la TV, selecciona la barra de direcciones y pega con el botón de teclado de {app}.",
  "Open the {app} app and tap Remote. On Android you can also use the TV Remote tile in Quick Settings. The first time, type the code the TV shows.": "Abre la app {app} y toca Control remoto. En Android también puedes usar el acceso Control remoto de TV en los ajustes rápidos. La primera vez, escribe el código que muestra la TV.",
  "On the TV, open a web browser and select the address bar.": "En la TV, abre un navegador web y selecciona la barra de direcciones.",
  "Your phone keyboard opens. Touch and hold, tap Paste, then Enter.": "Se abre el teclado del teléfono. Mantén pulsado, toca Pegar y luego Intro.",
  "Many Google TV and Android TV devices have no browser. Install a free browser from the Play Store on the TV, or install our TV app instead.": "Muchos dispositivos Google TV y Android TV no tienen navegador. Instala un navegador gratis desde Play Store en la TV, o instala nuestra app para TV.",
  "On the Fire TV, open Silk (the Internet app) and select the address bar so the TV keyboard opens.": "En el Fire TV, abre Silk (la app Internet) y selecciona la barra de direcciones para que se abra el teclado de la TV.",
  "Open the {app} app on your phone, pick your Fire TV and type the code the TV shows the first time.": "Abre la app {app} en el teléfono, elige tu Fire TV y escribe el código que muestra la TV la primera vez.",
  "Tap the keyboard button, touch and hold the text box, tap Paste, then Enter.": "Toca el botón de teclado, mantén pulsado el cuadro de texto, toca Pegar y luego Intro.",
  "The keyboard has to be open on the TV first, or the phone has nothing to type into.": "Primero tiene que estar abierto el teclado en la TV; si no, el teléfono no tiene dónde escribir.",
  "Open the TV's web browser.": "Abre el navegador web de la TV.",
  "Type the short address shown above once, or press the microphone on the remote and say it.": "Escribe una vez la dirección corta de arriba, o pulsa el micrófono del control remoto y dila.",
  "Bookmark it or pin it to the TV home screen, so next time it is one click.": "Guárdalo en marcadores o fíjalo en la pantalla de inicio de la TV para que la próxima vez sea un clic.",
  "Open or get {app}": "Abrir u obtener {app}",
