  "After the first time": "Después de la primera vez",
  "Bookmark the page in the TV browser, or pin it to the TV home screen. On Google TV and Android TV you can also install our TV app for its own icon.": "Guarda la página en los marcadores del navegador de la TV o fíjala en la pantalla de inicio. En Google TV y Android TV también puedes instalar nuestra app para TV con su propio icono.",
  "What a website can't do": "Lo que una web no puede hacer",
  "Find your TV on the Wi-Fi and open its browser by itself. Only the TV maker's app can do that, which is why the steps use it.": "Encontrar tu TV en la Wi-Fi y abrir su navegador por sí sola. Solo la app del fabricante de la TV puede hacerlo; por eso los pasos la usan.",
  "Screen mirroring (Smart View, AirPlay) only copies your phone's screen. It doesn't open the TV browser.": "La duplicación de pantalla (Smart View, AirPlay) solo copia la pantalla del teléfono. No abre el navegador de la TV.",
