  "The order was cancelled.": "El pedido se canceló.",
  "No SMS arrived before the number expired.": "No llegó ningún SMS antes de que caducara el número.",
  "Expires in {time}": "Caduca en {time}",
  "No messages yet.": "Aún no hay mensajes.",
  "until {date}": "hasta el {date}",
  "Mail": "Correo",
  "Open Yandex Mail settings › Mail clients and turn on IMAP (portal password or app password).": "Abre los ajustes de Yandex Mail › Programas de correo y activa IMAP (contraseña del portal o de aplicación).",
  "Open Yandex ID › Security › App passwords, choose Mail, name it ViktorychApp and copy the password.": "Abre Yandex ID › Seguridad › Contraseñas de aplicaciones, elige Correo, llámala ViktorychApp y copia la contraseña.",
  "Create a folder named ViktorychApp.": "Crea una carpeta llamada ViktorychApp.",
  "Settings › Message filtering › Create filter, then paste the rule below.": "Ajustes › Filtrado de mensajes › Crear filtro y pega la regla de abajo.",
  "If: From contains \"simplelogin\"\nOr: To contains \"@{alias-domain}\"\nThen: Move to folder \"ViktorychApp\"\nApply to existing messages: on": "Si: De contiene \"simplelogin\"\nO: Para contiene \"@{alias-domain}\"\nEntonces: Mover a la carpeta \"ViktorychApp\"\nAplicar a los mensajes existentes: sí",
  "Turn on 2-Step Verification for your Google account (app passwords need it).": "Activa la verificación en dos pasos en tu cuenta de Google (las contraseñas de aplicación la necesitan).",
  "Open Google Account › App passwords, name it ViktorychApp and copy the 16-letter password.": "Abre Cuenta de Google › Contraseñas de aplicaciones, llámala ViktorychApp y copia la contraseña de 16 letras.",
  "Create a label named ViktorychApp. In IMAP a label is a folder.": "Crea una etiqueta llamada ViktorychApp. En IMAP una etiqueta es una carpeta.",
  "Settings › Filters › Create a new filter, paste the search below, then choose Skip the Inbox and Apply the label ViktorychApp.": "Ajustes › Filtros › Crear un filtro nuevo, pega la búsqueda de abajo y elige Omitir Recibidos y Aplicar la etiqueta ViktorychApp.",
  "Turn on two-step verification for your Microsoft account.": "Activa la verificación en dos pasos en tu cuenta de Microsoft.",
  "Open Security › App passwords and create one. Some Outlook.com accounts no longer allow IMAP with an app password; if the test fails, use Yandex or Gmail.": "Abre Seguridad › Contraseñas de aplicación y crea una. Algunas cuentas de Outlook.com ya no permiten IMAP con contraseña de aplicación; si la prueba falla, usa Yandex o Gmail.",
  "Settings › Mail › Rules › Add new rule, then use the rule below.": "Configuración › Correo › Reglas › Agregar nueva regla y usa la regla de abajo.",
  "Condition: From includes \"simplelogin\"\nAction: Move to \"ViktorychApp\"\nStop processing more rules: on": "Condición: De incluye \"simplelogin\"\nAcción: Mover a \"ViktorychApp\"\nDejar de procesar más reglas: sí",
  "Open Settings › Mail programs and allow IMAP access.": "Abre Ajustes › Programas de correo y permite el acceso IMAP.",
  "Open Security › Passwords for external apps, create one for ViktorychApp and copy it.": "Abre Seguridad › Contraseñas para aplicaciones externas, crea una para ViktorychApp y cópiala.",
  "Settings › Filters › Add filter, then use the rule below.": "Ajustes › Filtros › Añadir filtro y usa la regla de abajo.",
  "If: From contains \"simplelogin\"\nThen: Move to folder \"ViktorychApp\"": "Si: De contiene \"simplelogin\"\nEntonces: Mover a la carpeta \"ViktorychApp\"",
  "The mailbox refused the email or app password.": "El buzón rechazó el correo o la contraseña de aplicación.",
  "That folder doesn't exist. Check the name, including capital letters.": "Esa carpeta no existe. Revisa el nombre, incluidas las mayúsculas.",
  "Pick a dedicated folder. INBOX needs the extra switch below.": "Elige una carpeta dedicada. INBOX necesita el interruptor adicional de abajo.",
  "Too many checks. Trying again shortly.": "Demasiadas comprobaciones. Lo intentaremos de nuevo en breve.",
  "Mail isn't available yet.": "El correo aún no está disponible.",
