  "Sections with their own page are not shown here.": "Las secciones con página propia no se muestran aquí.",
  "Customize Discord": "Personalizar Discord",
  "Hide channel": "Ocultar canal",
  "Hide message previews": "Ocultar vista previa de mensajes",
  "New message": "Mensaje nuevo",
  "Previews on": "Vista previa activada",
  "Saved on this device only. Private channels show “New message” in previews and alerts instead of the text. Nothing is sent to Discord.": "Se guarda solo en este dispositivo. Los canales privados muestran «Mensaje nuevo» en vistas previas y alertas en lugar del texto. No se envía nada a Discord.",
  "Show message previews": "Mostrar vista previa de mensajes",
  "Nearby chat (Bitchat)": "Chat cercano (Bitchat)",
  "The backup chat offered when nothing else loads: Bluetooth on the TV app, public Nostr area chat in browsers.": "El chat de respaldo que se ofrece cuando nada más carga: Bluetooth en la app de TV y chat de zona público por Nostr en navegadores.",
  "Nearby chat": "Chat cercano",
  "A backup way to talk when the app can't reach its servers. On the TV app it uses Bluetooth to chat with people nearby. In a browser it uses an area chat over public Nostr relays. Both work with the Bitchat app. Messages here are public; anyone in the area can read them.": "Una forma de respaldo para hablar cuando la app no llega a sus servidores. En la app de TV usa Bluetooth para chatear con personas cercanas. En un navegador usa un chat de zona a través de relays públicos de Nostr. Ambos funcionan con la app Bitchat. Los mensajes aquí son públicos; cualquiera en la zona puede leerlos.",
  "Offer nearby chat when nothing else loads": "Ofrecer chat cercano cuando nada más cargue",
  "It never runs by itself. It is offered only when the app can't load at all, and it connects only while the chat is open.": "Nunca se activa solo. Se ofrece solo cuando la app no puede cargar, y se conecta solo mientras el chat está abierto.",
  "Open nearby chat": "Abrir chat cercano",
  "Area (geohash)": "Zona (geohash)",
  "Nostr relays, separated by spaces (wss://…). Leave empty for the defaults.": "Relays de Nostr, separados por espacios (wss://…). Déjalo vacío para usar los predeterminados.",
  "Your name in the chat": "Tu nombre en el chat",
  "Type a message": "Escribe un mensaje",
  "Pick an area to start, such as u3qc for a city or u3qcn for a district.": "Elige una zona para empezar, como u3qc para una ciudad o u3qcn para un barrio.",
  "That is not a geohash. Use letters and digits like u3qcn.": "Eso no es un geohash. Usa letras y números como u3qcn.",
  "{up} of {all} relays connected": "{up} de {all} relays conectados",
  "No messages in the last hour yet.": "Aún no hay mensajes en la última hora.",
  "Location is not available. Type an area instead.": "La ubicación no está disponible. Escribe una zona.",
  "You are offline. The browser area chat needs some internet; the TV app can use Bluetooth.": "Estás sin conexión. El chat de zona del navegador necesita algo de internet; la app de TV puede usar Bluetooth.",
  "Sharing pool": "Grupo para compartir",
  "Off while Save data is on.": "Desactivado mientras Ahorro de datos está activado.",
  "Off on mobile data.": "Desactivado con datos móviles.",
  "Auto waits for an unmetered Wi-Fi or wired connection.": "Automático espera una conexión Wi-Fi o por cable sin límite de datos.",
  "Auto waits until this device is charging.": "Automático espera a que este dispositivo esté cargando.",
  "Off in TV mode unless you choose On.": "Desactivado en modo TV salvo que elijas Activado.",
  "Off.": "Desactivado.",
  "Sign in to join the pool.": "Inicia sesión para unirte al grupo.",
  "On, connected to {n} devices.": "Activado, conectado a {n} dispositivos.",
  "Saved {saved} from peers, shared {shared}": "Ahorrado {saved} gracias a otros, compartido {shared}",
  "Sharing pool, last 7 days": "Grupo para compartir, últimos 7 días",
  "Peer hit rate {rate} ({hits} of {tries})": "Aciertos entre pares {rate} ({hits} de {tries})",
  "Offloaded from the server {peer} of {total} ({share})": "Descargado del servidor {peer} de {total} ({share})",
  "Online in the pool now {n} · rejected chunks {bad}": "En línea en el grupo ahora {n} · fragmentos rechazados {bad}",
  "Helping while our servers can't be reached: getting posts from {n} devices, uploading nothing.": "Ayudando mientras no se puede llegar a nuestros servidores: recibiendo publicaciones de {n} dispositivos, sin subir nada.",
  "When our servers are blocked or failing, devices in the pool can still pass you the newest posts, checked against the same signed fingerprint. On mobile data this needs On, and nothing is uploaded from mobile data. Photos and videos from other sites can't be checked, so they aren't shared.": "Cuando nuestros servidores están bloqueados o fallan, los dispositivos del grupo aún pueden pasarte las publicaciones más recientes, comprobadas con la misma huella firmada. Con datos móviles hace falta elegir Activado, y no se sube nada con datos móviles. Las fotos y videos de otros sitios no se pueden comprobar, así que no se comparten.",
  "Got {n} updates from peers while the server was out of reach": "Recibiste {n} actualizaciones de otros mientras el servidor no respondía",
  "Connection is slow - new posts came from other devices": "La conexión es lenta - las publicaciones nuevas llegaron de otros dispositivos",
  "Devices that turned this on pass each other files they already have: feed files, app files and other posts, each named only by its fingerprint, never by an account or list name. Pages load from nearby and the server works less. Every file is checked against its fingerprint before it is used.": "Los dispositivos que lo activaron se pasan entre sí archivos que ya tienen: archivos del feed, de la app y otras publicaciones, cada uno nombrado solo por su huella, nunca por el nombre de una cuenta o lista. Las páginas cargan desde cerca y el servidor trabaja menos. Cada archivo se comprueba con su huella antes de usarse.",
  "Like any WebRTC connection, the devices you share with can see your IP address. Only people who turned this on connect, at most 4 at a time, and no relay server is used. Up to 20 MB a day is shared from this device, 40 MB on Wi-Fi while charging, and less on low battery or in the background.": "Como en cualquier conexión WebRTC, los dispositivos con los que compartes pueden ver tu dirección IP. Solo se conectan quienes lo activaron, como máximo 4 a la vez, y no se usa ningún servidor de retransmisión. Este dispositivo comparte hasta 20 MB al día, 40 MB con Wi-Fi mientras carga, y menos con poca batería o en segundo plano.",
  "Choose sources and sharing automatically": "Elegir fuentes y uso compartido automáticamente",
  "Uses the fastest of nearby devices and our servers, loads what is on screen first, and shares less on low battery, mobile data or in the background.": "Usa lo más rápido entre los dispositivos cercanos y nuestros servidores, carga primero lo que está en pantalla y comparte menos con poca batería, datos móviles o en segundo plano.",
