  "A short guided walkthrough. Or paste a key you already have below.": "Una guía breve. O pega abajo una clave que ya tengas.",
  "I already have a key": "Ya tengo una clave",
  "Step 1 · Open Discord": "Paso 1 · Abre Discord",
  "Sign in with a SPARE account, not your main one. Discord may lock accounts used this way.": "Inicia sesión con una cuenta de RESERVA, no con la principal. Discord puede bloquear las cuentas usadas así.",
  "Open Discord": "Abrir Discord",
  "I'm signed in": "Ya inicié sesión",
  "Step 2 · Copy your key": "Paso 2 · Copia tu clave",
  "This step needs a desktop browser. Open this page on a computer to copy the key, or paste a key you already have.": "Este paso necesita un navegador de escritorio. Abre esta página en un ordenador para copiar la clave, o pega una que ya tengas.",
  "In the Discord tab, open the developer console: F12, or Ctrl+Shift+I (Cmd+Option+I on a Mac).": "En la pestaña de Discord, abre la consola de desarrollador: F12, o Ctrl+Mayús+I (Cmd+Opción+I en un Mac).",
  "Copy the snippet below, paste it into the console and press Enter.": "Copia el fragmento de abajo, pégalo en la consola y pulsa Enter.",
  "It copies your key to the clipboard. Come back here and paste it in the next step.": "Copia tu clave al portapapeles. Vuelve aquí y pégala en el siguiente paso.",
  "What it does: it reads your own account's key and copies it to your clipboard. It is not sent anywhere.": "Qué hace: lee la clave de tu propia cuenta y la copia al portapapeles. No se envía a ningún sitio.",
  "Console snippet": "Fragmento de consola",
  "Copy snippet": "Copiar fragmento",
  "Discord will show a red “Self-XSS” warning.": "Discord mostrará un aviso rojo de «Self-XSS».",
  "That warning is there because pasting code someone else gives you can hand them your account. This snippet is safe only because you can read exactly what it does above. Never paste code you do not understand.": "Ese aviso existe porque pegar código que te da otra persona puede entregarle tu cuenta. Este fragmento es seguro solo porque puedes leer exactamente qué hace arriba. Nunca pegues código que no entiendas.",
  "Step 3 · Paste your key": "Paso 3 · Pega tu clave",
  "Paste the key you copied. It is checked straight from this device and kept here only.": "Pega la clave que copiaste. Se comprueba desde este dispositivo y se guarda solo aquí.",
