  "NZlay account": "Cuenta de NZlay",
  "NZlay didn’t accept that email and password.": "NZlay no aceptó ese correo y contraseña.",
  "NZlay doesn’t let this account post here.": "NZlay no permite que esta cuenta publique aquí.",
  "NZlay forum": "Foro de NZlay",
  "NZlay forum ReGone links": "Enlaces de ReGone en el foro de NZlay",
  "NZlay forum community": "Comunidad del foro de NZlay",
  "NZlay forum posting": "Publicar en el foro de NZlay",
  "NZlay has no sign-in for other apps, so you sign in with your NZlay email and password here. Your password goes once to NZlay and is never kept. The NZlay session that comes back is encrypted and kept only in this browser. Posts go out only when you tap Post or Reply.": "NZlay no tiene inicio de sesión para otras apps, así que aquí inicias sesión con tu correo y contraseña de NZlay. Tu contraseña se envía una vez a NZlay y nunca se guarda. La sesión de NZlay que se devuelve se cifra y se guarda solo en este navegador. Las publicaciones solo se envían cuando tocas Publicar o Responder.",
  "NZlay isn’t answering right now.": "NZlay no responde ahora mismo.",
  "NZlay member": "Miembro de NZlay",
  "NZlay says that session is signed out.": "NZlay dice que esa sesión está cerrada.",
  "NZlay sign-in is turned off.": "El inicio de sesión de NZlay está desactivado.",
  "NZlay signed you out. Sign in again.": "NZlay cerró tu sesión. Inicia sesión de nuevo.",
  "NZlay wants to check that you’re a person. Sign in on NZlay, solve its check there, then come back and paste your session below.": "NZlay quiere comprobar que eres una persona. Inicia sesión en NZlay, resuelve su comprobación allí y luego vuelve y pega tu sesión abajo.",
  "NZlay wants to check that you’re a person. Your text is copied; finish on NZlay.": "NZlay quiere comprobar que eres una persona. Tu texto está copiado; finaliza en NZlay.",
