  "{name} shortcuts": "Atajos de {name}",
  "Removing the icon doesn't delete your data on Android or computers. Use Settings → Delete all data on this device.": "Quitar el icono no borra tus datos en Android ni en ordenadores. Usa Configuración → Eliminar todos los datos de este dispositivo.",
  "Checking how much is stored on this device…": "Comprobando cuánto hay guardado en este dispositivo…",
  "Delete private data if the app isn't opened for": "Eliminar datos privados si la app no se abre durante",
  "Sign-in, drafts, messages and private lists on this device are deleted the next time the app opens after this long.": "El inicio de sesión, los borradores, los mensajes y las listas privadas de este dispositivo se eliminan la próxima vez que se abra la app tras este tiempo.",
  "Also delete saved posts and media": "Eliminar también las publicaciones y archivos guardados",
  "Delete all data on this device": "Eliminar todos los datos de este dispositivo",
  "Signs you out here and removes everything this app saved in this browser. Your account and posts stay on the server.": "Cierra tu sesión aquí y quita todo lo que esta app guardó en este navegador. Tu cuenta y tus publicaciones siguen en el servidor.",
  "Delete this app's data from your browser": "Eliminar los datos de esta app del navegador",
  "Chrome on Android:": "Chrome en Android:",
  "Settings → Site settings → All sites → this site → Clear & reset.": "Configuración → Configuración de sitios → Todos los sitios → este sitio → Borrar y restablecer.",
  "iPhone and iPad:": "iPhone y iPad:",
  "Deleting the Home Screen app removes its data. In Safari, also use Settings → Apps → Safari → Advanced → Website Data.": "Eliminar la app de la pantalla de inicio borra sus datos. En Safari, usa también Ajustes → Apps → Safari → Avanzado → Datos de sitios web.",
  "Chrome or Edge on a computer:": "Chrome o Edge en un ordenador:",
  "Click the icon left of the address, then Site settings → Delete data.": "Haz clic en el icono a la izquierda de la dirección y luego en Configuración de sitios → Eliminar datos.",
  "Firefox:": "Firefox:",
