  "Safari on Mac:": "Safari en Mac:",
  "Safari → Settings → Privacy → Manage Website Data → this site → Remove.": "Safari → Ajustes → Privacidad → Gestionar datos de sitios web → este sitio → Eliminar.",
  "This browser doesn't report how much is stored.": "Este navegador no indica cuánto hay guardado.",
